local VERSION='10.0.0'
local commandSimulations, evaluations, remediation = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('CreateCommandSimulationV10',function(name,objectives,difficulty,author)local item={id=uid('SIM10'),name=name,objectives=objectives or{},difficulty=difficulty or'advanced',author=author,status='draft',events={},createdAt=os.time()};commandSimulations[item.id]=item;return item.id,item end)
exports('ScoreCommandPerformanceV10',function(simulationId,actions,standards)local score=100;local misses={};for _,standard in ipairs(standards or{})do local found=false;for _,action in ipairs(actions or{})do if action.code==standard.code and(tonumber(action.minutes)or 999)<=tonumber(standard.targetMinutes or 999)then found=true break end end;if not found then score=score-(tonumber(standard.penalty)or 10);misses[#misses+1]=standard.code end end;local item={id=uid('EVAL10'),simulationId=simulationId,score=math.max(0,score),misses=misses,createdAt=os.time()};evaluations[item.id]=item;return item end)
exports('AssignRemediationV10',function(providerId,competencies,educator)local item={id=uid('REM10'),providerId=providerId,competencies=competencies or{},educator=educator,status='assigned',createdAt=os.time()};remediation[item.id]=item;return true,item end)
exports('GetV10TrainingBoard',function()return{version=VERSION,commandSimulations=commandSimulations,evaluations=evaluations,remediation=remediation,generatedAt=os.time()}end)
CreateThread(function()Wait(7800);print('[dpn-medical-training] v10 command simulation and competency remediation active')end)
